(async()=>{
 const check=(ok,msg)=>{if(!ok)throw Error(msg)},pause=ms=>new Promise(r=>setTimeout(r,ms));
 const field=id=>document.getElementById(id),stats={};
 await notebookShow('model');
 const formal=field('chat-system'),draft=field('chat-system-standby'),fold=draft.closest('details');
 check(fold&&!fold.open,'System standby must start collapsed');
 check(fold.compareDocumentPosition(formal)&Node.DOCUMENT_POSITION_FOLLOWING,'Standby must precede formal prompt');
 check(formal.readOnly,'System prompt must be readonly');
 check([...field('chat-side-model').querySelectorAll('button[onclick*="chatSavePromptStandby"]')].every(b=>fold.contains(b)),'Save button is outside fold');
 fold.open=true;draft.value='新的系统设定 🐈';chatSystemPromptStandbyEdited();
 const before=chatLoadConfig().system;let pending=chatSyncPromptNow('system');
 check(field('ckActionModal').classList.contains('show'),'Sync did not ask for confirmation');
 field('ck-action-cancel').click();check(await pending===false&&chatLoadConfig().system===before,'Cancel changed formal prompt');
 pending=chatSyncPromptNow('system');field('ck-action-confirm').click();check(await pending===true,'Immediate sync failed');
 check(formal.value===draft.value&&chatLoadConfig().system===draft.value,'Confirmed content was not saved');
 check(field('chat-system-count').textContent.includes(String(Array.from(draft.value).length)),'Wrong system character count');
 fold.open=false;
 await notebookShow('thinking');
 const thinking=field('chat-thinking-prompt'),thinkingDraft=field('chat-thinking-standby'),thinkingFold=thinkingDraft.closest('details');
 check(!thinkingFold.open&&thinking.readOnly,'Thinking standby/read-only state missing');
 thinkingFold.open=true;thinkingDraft.value='先梳理事实，再作答。';chatThinkingPromptStandbyEdited();
 pending=chatSyncPromptNow('thinking');field('ck-action-confirm').click();check(await pending,'Thinking sync failed');
 check(thinking.value===thinkingDraft.value&&chatLoadConfig().fakeThinkingPrompt===thinking.value,'Native/compatible prompt aliases disagree');
 thinkingFold.open=false;
 await notebookShow('chat');
 const input=field('chat-input');input.value='';chatAutosizeInput(input);await pause(50);
 const base=input.getBoundingClientRect().height;
 chatMessages=[{role:'pending_user',text:'很长的待发送内容。'.repeat(40),pendingId:'editing',ts:Date.now()}];chatCurrentSession().messages=chatMessages;chatRenderMessages();
 chatStartEditMessage(0);check(document.body.classList.contains('chat-editing'),'Editing did not start');
 input.value='保存之后只有一行';check(chatSaveEditedMessage(),'Pending edit failed');
 const savedHeight=input.getBoundingClientRect().height;check(Math.abs(base-savedHeight)<2,'Composer remains tall after save: '+base+' -> '+savedHeight);
 check(chatMessages[0].text==='保存之后只有一行'&&chatMessages[0].role==='pending_user','Pending message state lost');
 chatStartEditMessage(0);chatCancelEdit();check(Math.abs(input.getBoundingClientRect().height-base)<2,'Composer remains tall after cancel');
 stats.composer={base,savedHeight};
 chatTogglePlus(true);let cfg=chatLoadConfig();cfg.splitAssistantReplies=true;chatSaveConfigObject(cfg);chatUpdateSplitReplyButton(cfg);
 const split=field('chat-split-replies-btn');const on=getComputedStyle(split.querySelector('svg')).color;
 split.focus();split.click();const off=getComputedStyle(split.querySelector('svg')).color;
 check(split.getAttribute('aria-pressed')==='false'&&split.querySelector('b').textContent==='整段','Split mode did not change immediately');
 check(on!==off,'Off icon retained active color');stats.splitColors={on,off};
 split.click();check(split.getAttribute('aria-pressed')==='true','Split could not turn on again');
 await notebookShow('display');chatToggleSearch(true);check(!field('chat-search').hidden,'Search could not open');
 field('chat-search-enabled').checked=false;chatSaveConfig(true);
 check(field('chat-search').hidden&&getComputedStyle(field('chat-search-toggle')).display==='none','Disabling search did not hide both icon and panel');
 chatToggleSearch(true);check(field('chat-search').hidden,'Programmatic open bypassed disabled setting');
 field('chat-search-enabled').checked=true;chatSaveConfig(true);check(getComputedStyle(field('chat-search-toggle')).display!=='none','Search icon did not restore');
 await notebookShow('time');field('chat-minimal-time-enabled').checked=true;chatSaveConfig(true);cfg=chatLoadConfig();
 check(cfg.minimalTimeEnabled&&cfg.minimalTimeCleanEachRound===false,'Minimal time default retention is wrong');
 field('chat-minimal-time-clean-each-round').checked=true;chatSaveConfig(true);check(chatLoadConfig().minimalTimeCleanEachRound,'Cleanup setting not saved');
 await notebookShow('digest');
 const reserve=field('chat-digest-detail').closest('details');check(!reserve.open,'Summary reserve must start collapsed');
 check(field('chat-daily-digest-pack').readOnly,'Injection preview should not be editable');
 cfg=chatLoadConfig();cfg.dailyDigestEnabled=true;cfg.dailyDigestRetentionDays=3;cfg.dailyDigestDetailDays=1;cfg.dailyDigestRollupDays=2;chatSaveConfigObject(cfg);
 const today=chatDailyDigestDayKey(Date.now()),session=chatCurrentSession();session.messages=[];chatMessages=session.messages;
 session.dailyDigests=[3,2,1,0].map(n=>{const day=chatDigestShiftDay(today,-n),ts=new Date(day+'T12:00:00').getTime();return {dayKey:day,startTs:ts,endTs:ts,text:n?'第 '+n+' 天保留的事件和约定。':'今天的新事情。'}});
 session.digestRollup=null;chatRenderDailyDigest(cfg);
 const calls=[];window.fetch=async(url,options)=>{const body=JSON.parse(options.body);calls.push({url,options,body});return {ok:true,json:async()=>({ok:true,status:'queued',pending_groups:0,accepted_keys:[],snapshot:{revision:1,source_stamp:body.base_stamp,base:body.base,result:null}})}};
 panelAuthKey='fixture-key';cfg.panelKey='fixture-key';chatSaveConfigObject(cfg);chatWriteForm(cfg);
 check(await chatRefreshDigestNow('rollup'),'Nightly digest queue failed');
 check(calls.length===1&&/\/queue\?/.test(calls[0].url)&&calls[0].options.method==='POST','Manual digest sync must enqueue server work');
 const pack=field('chat-daily-digest-pack').value;
 check(pack.indexOf('第 1 天')<pack.indexOf('今天的新事情'),'Wrong injection order');
 field('chat-digest-detail-days').value='3';field('chat-digest-rollup-days').value='1';chatDigestSettingsEdited();
 check(chatSaveDailyDigestSetting()===null&&chatLoadConfig().dailyDigestDetailDays===1,'x+y>n was accepted');
 field('chat-digest-detail-days').value='1';field('chat-digest-rollup-days').value='2';chatSaveDailyDigestSetting();await chatDailyDigestChain;
 check(field('chat-daily-digest-save-status').textContent.includes('每天04:00后台更新'),'Settings save did not report the nightly schedule');
 reserve.open=true;const detail=field('chat-digest-detail');detail.value+='\n\n草稿里的补充';chatDigestEditorChanged('detail');const unsaved=detail.value;
 chatRenderDailyDigest(cfg);check(detail.value===unsaved,'Render overwrote an unsaved summary draft');
 session.dailyDigests[0].text+='后台已保存的更新';check(chatSaveDigestEditor('detail')===false,'Concurrent summary edit overwrote newer saved content');
 check(detail.value===unsaved,'Conflict discarded draft');chatResetDigestEditor('detail');
 const dayText=field('chat-digest-today');dayText.value='手工保存的当日新总结。';chatDigestEditorChanged('today');check(chatSaveDigestEditor('today'),'Today edit could not save');await chatDailyDigestChain;
 check(field('chat-daily-digest-pack').value.endsWith('手工保存的当日新总结。'),'Today edit did not reach injection preview');
 const normalized=chatNormalizeSession(JSON.parse(JSON.stringify(session)));
 check(normalized.digestRollup===null,'Queue synchronization must not invent a local rollup');
 check(normalized.dailyDigests.length===4,'Normalization lost daily records');
 check(field('chat-side-digest').scrollWidth<=field('chat-side-digest').clientWidth+1,'Expanded digest overflows horizontally');
 stats.summaries={days:normalized.dailyDigests.length,headers:field('chat-daily-digest-pack').value.match(/^【.*】/gm),requests:calls.length};
 closeToast();reserve.open=false;field('chat-side-digest').scrollTop=0;
 return stats;
})()
